const require_displaywidth = require('./displaywidth.cjs');

//#region src/text-layout.ts
/**
* Measures physical lines after removing terminal escape sequences.
* Empty text occupies one empty line; a trailing LF adds an empty final line.
* @param text Rendered text, possibly containing ANSI styles or OSC links.
* @returns First, last and widest line widths, and the number of lines.
* @internal
*/
function measureText(text) {
	const lines = require_displaywidth.stripAnsi(text).split("\n");
	const widths = lines.map(require_displaywidth.getDisplayWidth);
	return {
		firstLineWidth: widths[0],
		lastLineWidth: widths[widths.length - 1],
		maxLineWidth: widths.reduce((widest, width) => Math.max(widest, width), 0),
		lineCount: lines.length
	};
}
/**
* Appends rendered text to a cursor, optionally moving it to a fresh line.
* Measures the actual join so combining sequences crossing the boundary are
* handled correctly. Hard breaks reset both the line and any external offset.
* This never reflows the text itself or changes its escape sequences.
* @param text Text to append.
* @param cursor The current line and column.
* @param maxWidth Optional column budget.
* @param trailingRoom Space to leave after a single-line block. An annotation
* prefix reserves one column for content; a multiline prefix already has a
* hard break, so its first line needs no reservation.
* @returns The placed text (possibly with a leading LF) and resulting cursor.
* @internal
*/
function placeText(text, cursor, maxWidth, trailingRoom = 0) {
	const plain = require_displaywidth.stripAnsi(text);
	const lines = plain.split("\n");
	const offset = cursor.column - require_displaywidth.getDisplayWidth(cursor.line);
	const joinedWidth = offset + require_displaywidth.getDisplayWidth(cursor.line + lines[0]);
	const room = lines.length === 1 ? trailingRoom : 0;
	const breaks = maxWidth != null && (cursor.column > 0 || room > 0) && (joinedWidth > cursor.column || room > 0) && joinedWidth + room > maxWidth;
	const lastLine = lines[lines.length - 1];
	return {
		text: breaks ? "\n" + text : text,
		cursor: lines.length > 1 || breaks ? {
			line: lastLine,
			column: require_displaywidth.getDisplayWidth(lastLine)
		} : {
			line: cursor.line + plain,
			column: joinedWidth
		}
	};
}
const leadingSpacePattern = /^((?:\x1B(?:\[[0-9;:]*[@-~]|\][^\x1B\x07]*(?:\x1B\\|\x07)))*)[^\S\n]+/;
/**
* Removes the whitespace that begins a text's first line, keeping any
* escape sequences before it.  Used when layout moves text that starts with
* a separating space to a fresh line.
* @param text Rendered text, possibly containing ANSI styles or OSC links.
* @returns The text without its leading whitespace.
* @internal
*/
function trimLeadingSpace(text) {
	return text.replace(leadingSpacePattern, "$1");
}
/**
* Measures an annotation's fixed text without invoking theme callbacks.
* @param prefix The already joined prefix and optional label.
* @param suffix The closing text.
* @returns Geometry reserving at least one content column after the suffix's
* first-line width has been deducted from the formatter budget.
* @internal
*/
function measureAnnotation(prefix, suffix) {
	const prefixMetrics = measureText(prefix);
	const suffixMetrics = measureText(suffix);
	return {
		prefix,
		suffix,
		prefixMetrics,
		suffixMetrics,
		minWidth: Math.max(prefixMetrics.maxLineWidth, suffixMetrics.maxLineWidth, suffixMetrics.firstLineWidth + 1)
	};
}
/**
* Adds a separating space only when a label occupies its final physical line.
* @param label The rendered label, including any styles and hard breaks.
* @returns The label with spacing for the text that follows it.
* @internal
*/
function spaceAfterLabel(label) {
	return measureText(label).lastLineWidth > 0 ? label + " " : label;
}

//#endregion
exports.measureAnnotation = measureAnnotation;
exports.measureText = measureText;
exports.placeText = placeText;
exports.spaceAfterLabel = spaceAfterLabel;
exports.trimLeadingSpace = trimLeadingSpace;